code.source:
#include <iostream>
using namespace std;

int main() {
    int marks[5] = {72, 85, 64, 90, 58};
    cout << marks[0] << endl;
    cout << marks[4] << endl;
    marks[2] = 70;
    cout << marks[2] << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int marks[5] = {72, 85, 64, 90, 58};
    int sum = 0;
    for (int i = 0; i < 5; i++) {
        sum += marks[i];
    }
    cout << "Sum: " << sum << endl;
    return 0;
}

